package com.fileservice.auth

import io.ktor.server.application.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.http.*
import java.net.URI
import java.net.URLDecoder
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

data class OAuthConfig(
    val clientId: String,
    val clientSecret: String,
    val authorizedRedirectHosts: Set<String>,
    val baseUrl: String,
    val strictMode: Boolean
)

object ConfigLoader {
    fun load(): OAuthConfig {
        val env = System.getenv("DEPLOY_ENV") ?: "production"
        val strictMode = System.getenv("OAUTH_STRICT_REDIRECT") ?: "true"
        val allowedHosts = System.getenv("OAUTH_ALLOWED_HOSTS")
            ?: "files.example.com,app.example.com"

        // Fail closed: security-critical secrets must be explicitly provided.
        // Never fall back to a guessable default for the HMAC signing key /
        // OAuth client secret.
        val clientSecret = System.getenv("OAUTH_CLIENT_SECRET")
            ?: throw IllegalStateException("OAUTH_CLIENT_SECRET must be configured; refusing to start with a default secret")
        require(clientSecret.length >= 32) {
            "OAUTH_CLIENT_SECRET must be at least 32 characters of high-entropy secret material"
        }

        val clientId = System.getenv("OAUTH_CLIENT_ID")
            ?: throw IllegalStateException("OAUTH_CLIENT_ID must be configured")

        return OAuthConfig(
            clientId = clientId,
            clientSecret = clientSecret,
            authorizedRedirectHosts = allowedHosts.split(",").map { it.trim().lowercase() }.toSet(),
            baseUrl = System.getenv("SERVICE_BASE_URL") ?: "https://files.example.com",
            strictMode = strictMode.toBoolean()
        )
    }
}

class RedirectValidator(private val config: OAuthConfig) {

    private val schemeWhitelist = setOf("https")
    private val devSchemes = setOf("https", "http")

    fun validateRedirectUri(redirectUri: String): ValidationResult {
        if (redirectUri.isBlank()) {
            return ValidationResult.Invalid("Empty redirect URI")
        }

        val decoded = try {
            URLDecoder.decode(redirectUri, "UTF-8")
        } catch (e: Exception) {
            return ValidationResult.Invalid("Malformed URI encoding")
        }

        val uri = try {
            URI(decoded)
        } catch (e: Exception) {
            return ValidationResult.Invalid("Invalid URI syntax")
        }

        // Reject URIs with userinfo component (anti-phishing)
        if (uri.userInfo != null) {
            return ValidationResult.Invalid("URI must not contain userinfo")
        }

        // Reject fragment identifiers
        if (uri.fragment != null) {
            return ValidationResult.Invalid("URI must not contain fragments")
        }

        val allowedSchemes = if (config.strictMode) schemeWhitelist else devSchemes
        if (uri.scheme?.lowercase() !in allowedSchemes) {
            return ValidationResult.Invalid("Scheme not allowed: ${uri.scheme}")
        }

        // Host validation - the critical check
        val host = uri.host?.lowercase() ?: return ValidationResult.Invalid("No host")

        if (!isHostAuthorized(host)) {
            return ValidationResult.Invalid("Unauthorized host: $host")
        }

        // Port validation
        if (uri.port != -1 && uri.port != 443) {
            if (config.strictMode) {
                return ValidationResult.Invalid("Non-standard port in strict mode")
            }
        }

        return ValidationResult.Valid(decoded)
    }

    private fun isHostAuthorized(host: String): Boolean {
        return config.authorizedRedirectHosts.any { allowed ->
            hostMatchesPattern(host, allowed)
        }
    }

    private fun hostMatchesPattern(host: String, pattern: String): Boolean {
        // Exact match only - no subdomain wildcarding
        if (host == pattern) return true

        // Explicit wildcard prefix: pattern must start with "*." 
        // and host must be exactly one level deeper
        if (pattern.startsWith("*.")) {
            val baseDomain = pattern.removePrefix("*.")
            if (host == baseDomain) return true
            if (host.endsWith(".$baseDomain") && !host.removePrefix(host.substringBefore(".$baseDomain")).contains(".")) return false
            // Only allow direct subdomain, verified by counting dots
            val prefix = host.removeSuffix(".$baseDomain")
            if (host == "$prefix.$baseDomain" && !prefix.contains(".")) return true
        }

        return false
    }
}

sealed class ValidationResult {
    data class Valid(val uri: String) : ValidationResult()
    data class Invalid(val reason: String) : ValidationResult()
}

class StateTokenManager(private val secret: String) {
    fun generateState(sessionId: String, redirectUri: String): String {
        val payload = "$sessionId|$redirectUri|${System.currentTimeMillis()}"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secret.toByteArray(), "HmacSHA256"))
        val signature = Base64.getUrlEncoder().encodeToString(mac.doFinal(payload.toByteArray()))
        val encodedPayload = Base64.getUrlEncoder().encodeToString(payload.toByteArray())
        return "$encodedPayload.$signature"
    }

    fun verifyState(state: String, sessionId: String): StateVerification {
        val parts = state.split(".")
        if (parts.size != 2) return StateVerification.Invalid

        val payload = try {
            String(Base64.getUrlDecoder().decode(parts[0]))
        } catch (e: Exception) {
            return StateVerification.Invalid
        }

        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secret.toByteArray(), "HmacSHA256"))
        val expectedSig = Base64.getUrlEncoder().encodeToString(
            mac.doFinal(payload.toByteArray())
        )

        if (!MessageDigest.isEqual(expectedSig.toByteArray(), parts[1].toByteArray())) {
            return StateVerification.Invalid
        }

        val fields = payload.split("|")
        if (fields.size != 3) return StateVerification.Invalid
        if (fields[0] != sessionId) return StateVerification.Invalid

        val timestamp = fields[2].toLongOrNull() ?: return StateVerification.Invalid
        if (System.currentTimeMillis() - timestamp > 600_000) {
            return StateVerification.Expired
        }

        return StateVerification.Valid(fields[1])
    }
}

sealed class StateVerification {
    data class Valid(val redirectUri: String) : StateVerification()
    object Invalid : StateVerification()
    object Expired : StateVerification()
}

fun Application.configureOAuthRoutes() {
    val config = ConfigLoader.load()
    val validator = RedirectValidator(config)
    val stateManager = StateTokenManager(config.clientSecret)

    routing {
        get("/oauth/authorize") {
            val redirectUri = call.parameters["redirect_uri"]
                ?: return@get call.respondText("Missing redirect_uri", status = HttpStatusCode.BadRequest)
            val sessionId = call.request.cookies["session_id"]
                ?: return@get call.respondText("No session", status = HttpStatusCode.Unauthorized)

            when (val result = validator.validateRedirectUri(redirectUri)) {
                is ValidationResult.Valid -> {
                    val state = stateManager.generateState(sessionId, result.uri)
                    val authUrl = "https://idp.example.com/authorize?" +
                        "client_id=${config.clientId}&" +
                        "redirect_uri=${result.uri}&" +
                        "state=$state&response_type=code"
                    call.respondRedirect(authUrl)
                }
                is ValidationResult.Invalid -> {
                    call.respondText("Invalid redirect: ${result.reason}",
                        status = HttpStatusCode.BadRequest)
                }
            }
        }

        get("/oauth/callback") {
            val code = call.parameters["code"]
                ?: return@get call.respondText("Missing code", status = HttpStatusCode.BadRequest)
            val state = call.parameters["state"]
                ?: return@get call.respondText("Missing state", status = HttpStatusCode.BadRequest)
            val sessionId = call.request.cookies["session_id"]
                ?: return@get call.respondText("No session", status = HttpStatusCode.Unauthorized)

            when (val verification = stateManager.verifyState(state, sessionId)) {
                is StateVerification.Valid -> {
                    // Token exchange would happen here
                    call.respondRedirect(verification.redirectUri)
                }
                is StateVerification.Invalid -> {
                    call.respondText("Invalid state", status = HttpStatusCode.Forbidden)
                }
                is StateVerification.Expired -> {
                    call.respondText("State expired", status = HttpStatusCode.Gone)
                }
            }
        }
    }
}
